                                                  {name: algorithmName},
                                                  false, ["deriveBits", "deriveKey"]);
                  publicKey = await subtle.importKey("spki", test.vector,
                                                 {name: algorithmName},
                                                 false, [])
                  derived = await subtle.deriveKey({name: algorithmName, public: publicKey}, privateKey,
                                                   {name: "HMAC", hash: "SHA-256", length: 256}, true,
                                                   ["sign", "verify"]);
