    [0, 16].forEach(function (badIvLength) {
      var badIv = new Uint8Array(badIvLength);
      failing.push({
        name:
          'AES-OCB ' +
          keyLength.toString() +
          '-bit key, ' +
          'illegal iv length ' +
          (badIvLength << 3).toString() +
          '-bits',
        keyBuffer: keyBytes[keyLength],
        key: null,
        algorithm: {
          name: 'AES-OCB',
          iv: badIv,
          additionalData: additionalData,
          tagLength: 128,
        },
        plaintext: plaintext,
        result: ciphertext[keyLength][128],
      });
    });
  });

