    if (typeof bitCount === "undefined" && a.byteLength !== b.byteLength) {
        return false;
    }

    var aBytes = new Uint8Array(a);
    var bBytes = new Uint8Array(b);

    var length = a.byteLength;
    if (typeof bitCount !== "undefined") {
        length = Math.floor(bitCount / 8);
