function getTestVectors() {
  var vectors = [];

  // Basic test without context
  ['ML-DSA-44', 'ML-DSA-65', 'ML-DSA-87'].forEach((algorithmName) => {
    vectors.push({
      name: algorithmName + ' basic test',
      publicKeyBuffer: spki[algorithmName],
      publicKeyFormat: 'spki',
      publicKey: null,
      privateKeyBuffer: pkcs8[algorithmName],
      privateKeyFormat: 'pkcs8',
      privateKey: null,
      algorithmName: algorithmName,
      data: data,
      signature: signatures[algorithmName],
    });
  });

  return vectors;
}

// Invalid test vectors for negative testing
function getInvalidTestVectors() {
  var vectors = [];

  // Test with invalid signature
  ['ML-DSA-44', 'ML-DSA-65', 'ML-DSA-87'].forEach((algorithmName) => {
    vectors.push({
      name: algorithmName + ' invalid signature',
      publicKeyBuffer: spki[algorithmName],
      publicKeyFormat: 'spki',
      publicKey: null,
      privateKeyBuffer: pkcs8[algorithmName],
      privateKeyFormat: 'pkcs8',
      privateKey: null,
      algorithmName: algorithmName,
      data: data,
      signature: new Uint8Array([1, 2, 3, 4, 5]), // Invalid signature
    });
  });

  return vectors;
}
function run_test() {
  setup({ explicit_done: true });

  var subtle = self.crypto.subtle; // Change to test prefixed implementations

  // When are all these tests really done? When all the promises they use have resolved.
  var all_promises = [];

  // Source file [algorithm_name]_vectors.js provides the getTestVectors method
  // for the algorithm that drives these tests.
  var testVectors = getTestVectors();
  var invalidTestVectors = getInvalidTestVectors();

  // Test verification first, because signing tests rely on that working
  testVectors.forEach(function (vector) {
    var promise = importVectorKeys(vector, ['verify'], ['sign']).then(
      function (vectors) {
        var algorithm = vector.algorithmName;
        promise_test(function (test) {
          var operation = subtle
            .verify(algorithm, vector.publicKey, vector.signature, vector.data)
            .then(
              function (is_verified) {
                assert_true(is_verified, 'Signature verified');
              },
              function (err) {
                assert_unreached(
                  'Verification should not throw error ' +
                    vector.name +
                    ': ' +
                    err.message +
                    "'"
                );
              }
            );

          return operation;
        }, vector.name + ' verification');
      },
      function (err) {
        // We need a failed test if the importVectorKey operation fails, so
        // we know we never tested verification.
        promise_test(function (test) {
          assert_unreached(
            'importVectorKeys failed for ' +
              vector.name +
              ". Message: ''" +
              err.message +
              "''"
          );
        }, 'importVectorKeys step: ' + vector.name + ' verification');
      }
    );

    all_promises.push(promise);
  });

  // Test verification with an altered buffer during call
  testVectors.forEach(function (vector) {
    var promise = importVectorKeys(vector, ['verify'], ['sign']).then(
      function (vectors) {
        promise_test(function (test) {
          var signature = copyBuffer(vector.signature);
          signature[0] = 255 - signature[0];
          var operation = subtle
            .verify(
              {
                get name() {
                  signature[0] = vector.signature[0];
