function copyBuffer(sourceBuffer) {
    var source = new Uint8Array(sourceBuffer);
    var copy = new Uint8Array(sourceBuffer.byteLength)

    for (var i=0; i<source.byteLength; i++) {
        copy[i] = source[i];
    }

